body:
This PR fixes https://github.com/duckdblabs/duckdb-internal/issues/9946

Original problem, surfaced as:
```
Serialization Error: Failed to deserialize: field id mismatch, expected: 206, got: 210.
```
Which means we were expecting to read `parameters`, but those were never written when this got serialized.
So that means our check, guarding the reading of `parameters` does not agree with the logic that was encoded into `has_serialize`.
Our check is for `function.HasSerializationCallbacks()`, but it used to be `function.deserialize`.

#### Analysis

The problem stems from checking `function.serialize` and `function.deserialize` separately before, and now using `HasSerializationCallbacks()`.
Because `HasSerializationCallbacks` requires **both** `serialize` and `deserialize`.

#### Fixes

Writer fix: Make "function-serialize" and "logicalget-serialize" agree on needing `HasSerializationCallbacks`.
Reader fix: allow deserialization for functions that *used* to have a `serialize` callback, but don't anymore.

### `v2.0-cyanoptera`:
Write: Problematic: !! "function-serialize" needs `HasSerializationCallbacks`, "logicalget-serialize" needs `function.serialize` !!
Read: Problematic: !! "function-deserialize" checks for `HasSerializationBacks`, but only needs `function.deserialize`

serialize:
```c++
	FunctionSerializer::Serialize(serializer, function, bind_data.get());
	if (!function.serialize || serializer.ShouldSerialize(StorageVersion::V2_0_0)) {
		serializer.WriteProperty(206, "parameters", parameters);
		serializer.WriteProperty(207, "named_parameters", named_parameters);
		serializer.WriteProperty(208, "input_table_types", input_table_types);
		serializer.WriteProperty(209, "input_table_names", input_table_names);
	}
```
(Serialize)
```c++
		bool has_serialize = function.HasSerializationCallbacks();
		serializer.WriteProperty(503, "has_serialize", has_serialize);
		if constexpr (std::is_base_of_v<BoundSimpleFunction, FUNC>) {
			SerializeNamedArguments(serializer, function);
		}
		if (has_serialize) {
			serializer.WriteObject(504, "function_data",
			                       [&](Serializer &obj) { function.GetSerializeCallback()(obj, bind_info, function); });
			D_ASSERT(function.GetDeserializeCallback());
		}
```
deserialize:
```c++
	auto has_serialize = entry.second;
	unique_ptr<FunctionData> bind_data;
	if (has_serialize) {
		bind_data = FunctionSerializer::FunctionDeserialize(deserializer, function);
	}
```
```c++
	template <class FUNC>
	static unique_ptr<FunctionData> FunctionDeserialize(Deserializer &deserializer, FUNC &function) {
		if (!function.HasSerializationCallbacks()) {
			throw SerializationException("Function requires deserialization but no deserialization function for %s",
			                             function.GetName());
		}
		unique_ptr<FunctionData> result;
		deserializer.ReadObject(504, "function_data",
		                        [&](Deserializer &obj) { result = function.GetDeserializeCallback()(obj, function); });
		return result;
	}
```

### `v1.5.0`
Write: Problematic: !! "function-serialize" needs `HasSerializationCallbacks`, "logicalget-serialize" needs `function.serialize` !!
Read: Problematic: !! "function-deserialize" checks for `HasSerializationBacks`, but only needs `function.deserialize`

serialize:
```c++
	FunctionSerializer::Serialize(serializer, function, bind_data.get());
	if (!function.serialize) {
		D_ASSERT(!function.serialize);
		// no serialize method: serialize input values and named_parameters for rebinding purposes
		serializer.WriteProperty(206, "parameters", parameters);
		serializer.WriteProperty(207, "named_parameters", named_parameters);
		serializer.WriteProperty(208, "input_table_types", input_table_types);
		serializer.WriteProperty(209, "input_table_names", input_table_names);
	}
```
(Serialize)
```c++
		bool has_serialize = function.HasSerializationCallbacks();
		serializer.WriteProperty(503, "has_serialize", has_serialize);
		if (has_serialize) {
			serializer.WriteObject(504, "function_data",
			                       [&](Serializer &obj) { function.GetSerializeCallback()(obj, bind_info, function); });
			D_ASSERT(function.GetDeserializeCallback());
		}
```

deserialize:
```c++
	auto has_serialize = entry.second;
	unique_ptr<FunctionData> bind_data;
	if (!has_serialize) {
		deserializer.ReadProperty(206, "parameters", result->parameters);
		deserializer.ReadProperty(207, "named_parameters", result->named_parameters);
		deserializer.ReadProperty(208, "input_table_types", result->input_table_types);
		deserializer.ReadProperty(209, "input_table_names", result->input_table_names);
	} else {
		bind_data = FunctionSerializer::FunctionDeserialize(deserializer, function);
	}
```
```c++
	template <class FUNC>
	static unique_ptr<FunctionData> FunctionDeserialize(Deserializer &deserializer, FUNC &function) {
		if (!function.HasSerializationCallbacks()) {
			throw SerializationException("Function requires deserialization but no deserialization function for %s",
			                             function.name);
		}
		unique_ptr<FunctionData> result;
		deserializer.ReadObject(504, "function_data",
		                        [&](Deserializer &obj) { result = function.GetDeserializeCallback()(obj, function); });
		return result;
	}
```

### `v1.4.0`
Write: Both "function-serialize" and "logicalget-serialize" agree on `function.serialize`
Read: "function-deserialize" agrees on needing only `function.deserialize`

serialize same as v1.5.0, except for:
(Serialize)
```c++
		bool has_serialize = function.serialize;
		serializer.WriteProperty(503, "has_serialize", has_serialize);
		if (has_serialize) {
			serializer.WriteObject(504, "function_data",
			                       [&](Serializer &obj) { function.serialize(obj, bind_info, function); });
			D_ASSERT(function.deserialize);
		}
```
deserialize:
```c++
	if (!has_serialize) {
		deserializer.ReadProperty(206, "parameters", result->parameters);
		deserializer.ReadProperty(207, "named_parameters", result->named_parameters);
		deserializer.ReadProperty(208, "input_table_types", result->input_table_types);
		deserializer.ReadProperty(209, "input_table_names", result->input_table_names);
	} else {
		bind_data = FunctionSerializer::FunctionDeserialize(deserializer, function);
	}
```
```c++
	template <class FUNC>
	static unique_ptr<FunctionData> FunctionDeserialize(Deserializer &deserializer, FUNC &function) {
		if (!function.deserialize) {
			throw SerializationException("Function requires deserialization but no deserialization function for %s",
			                             function.name);
		}
		unique_ptr<FunctionData> result;
		deserializer.ReadObject(504, "function_data",
		                        [&](Deserializer &obj) { result = function.deserialize(obj, function); });
		return result;
	}
```
